def comb_sort(arr):
    n = len(arr)
    gap = n // 2
    while gap > 0:
        for i in range(gap, n):
            j = i + gap
            while j < n:
                if arr[j] < arr[i]:
                    arr[j], arr[i] = arr[i], arr[j]
                    j += gap
                else:
                    break
        gap //= 2
    return arr

