def max_path_sum(triangle, n, m):
    if n == 0 or m == 0:
        return 0
    if n == 1 or m == 1:
        return triangle[0][0]
    if n == 2 or m == 2:
        return triangle[0][0] + triangle[1][0] + triangle[2][0]
    return max(triangle[n-1][0] + max_path_sum(triangle, n-1, m-1), 
                triangle[n-1][0] + max_path_sum(triangle, n-1, m-2), 
                triangle[n-1][0] + max_path_sum(triangle, n-2, m-1))

def longest_subseq_with_diff_one(arr, diff):
    n = len(arr)
    dp = [[0] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = 1
    for i in range(n-1):
        for j in range(i+1, n):
            if arr[i] == arr[j] and abs(arr[i] - arr[j]) == diff:
                dp[i][j] = 1
    for i in range(n-1):
        for j in range(i+1, n):
            if dp[i][j] == 1:
                dp[i][j] = dp[i+1][j] + 1
    return max(max(dp[i][j] for i in range(n) for j in range(n)), max(dp[i][j] for i in range(n-1) for j in range(i+1)))

