def find_peak(arr):
    n = len(arr)
    if n == 0:
        return None
    if n == 1:
        return arr[0]
    if n == 2:
        return max(arr[0], arr[1])
    if n == 3:
        return max(arr[0], max(arr[1], arr[2]))
    if n == 4:
        return max(arr[0], max(arr[1], max(arr[2], arr[3])))
    if n == 5:
        return max(arr[0], max(arr[1], max(arr[2], max(arr[3], arr[4]))))
    if n == 6:
        return max(arr[0], max(arr[1], max(arr[2], max(arr[3], max(arr[4], arr[5])))))
    if n == 7:
        return max(arr[0], max(arr[1], max(arr[2], max(arr[3], max(arr[4], max(arr[5], arr[6])))))
    if n == 8:
        return max(arr[0], max(arr[1], max(arr[2], max(arr[3], max(arr[4], max(arr[5], max(arr[6], arr[7]))))))
    if n == 9:
        return max(arr[0], max(arr[1], max(arr[2], max(arr[3], max(arr[4], max(arr[5], max(arr[6], max(arr[7], arr[8]))))))
    if n == 10:
        return max(arr[0], max(arr[1], max(arr[2], max(arr[3], max(arr[4], max(arr[5], max(arr[6], max(arr[7], max(arr[8], arr[9]))))))

def decimal_to_Octal(n):
    octal = ""
    while n > 0:
        octal = str(n%8) + octal
        n = n//8
    return octal

def max_product(arr, n):
    max_product = 0
    for i in range(n):
        for j in range(i+1, n):
            product = arr[i] * arr[j]
            if product > max_product:
                max_product = product
    return max_product

def max_profit(prices, k):
    n = len(prices)
    if n < k:
        return 0
    elif n == k:
        return max(prices[-1] - prices[0], 0)
    else:
        max_profit = 0
        for i in range(1, n):
            max_profit = max(max_profit, prices[i] - prices[i-1])
        max_profit = max(max_profit, max(prices[-k:]) - prices[0])
        return max_profit

def add_pairwise(tuples):
    result = []
    for i in range(len(tuples)):
        for j in range(i + 1, len(tuples)):
            result.append(tuples[i] + tuples[j])
    return result

print(add_pairwise((1, 5, 7, 8, 10)))

def find_remainder(arr, n, k):
    remainder = 0
    for i in range(len(arr)):
        remainder += arr[i] * k
    return remainder % n

print(find_remainder([ 100, 10, 5, 25, 35, 14 ],6,11))

def check_Consecutive(lst):
    for i in range(len(lst)-1):
        if lst[i] + 1 != lst[i+1]:
            return False
    return True

def tuple_intersection(tuples):
    result = set()
    for tup in tuples:
        result.update(tup)
    return result

def get_max_occuring_char(string):
    char_count = {}
    for char in string:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1
    max_char = ""
    max_count = 0
    for char in char_count:
        if char_count[char] > max_count:
            max_char = char
            max_count = char_count[char]
    return max_char

def is_subset_sum(nums, target, sum):
    for i in range(len(nums)):
        for j in range(i+1, len(nums)+1):
            if sum == target:
                return True
            elif sum < target:
                return is_subset_sum(nums[i:], target, sum)
            else:
                return is_subset_sum(nums[j:], target, sum)

import re

def match(s):
    return re.search(r'[A-Z][a-z]+', s)

def first_Factorial_Divisible_Number(x):
    factorial = 1
    for i in range(1, x+1):
        factorial *= i
        if factorial % x == 0:
            return i
    return -1

def largest_palindrome(arr):
    largest = 0
    for num in arr:
        if is_palindrome(num):
            largest = max(largest, num)
    return largest

def is_palindrome(num):
    return str(num) == str(num)[::-1]

def frequency_Of_Largest(arr):
    max_val = max(arr)
    freq = 0
    for val in arr:
        if val == max_val:
            freq += 1
    return freq

print(frequency_Of_Largest([1,2,3,4,4]))

def extract_symmetric(lst):
    result = set()
    for i in range(len(lst)):
        for j in range(i + 1, len(lst)):
            if lst[i] == lst[j]:
                result.add((lst[i], lst[j]))
    return result

def sum_gp(a, r, n):
    if n == 0:
        return 0
    elif n == 1:
        return a
    else:
        return a + r * sum_gp(a, r, n-1)

def binary_search(arr, x):
    low = 0
    high = len(arr) - 1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == x:
            return mid
        elif arr[mid] < x:
            low = mid + 1
        else:
            high = mid - 1
    return -1

def calculate_polygons(x, y, z, w, h):
    polygons = []
    for i in range(x):
        for j in range(y):
            for k in range(z):
                for l in range(w):
                    polygons.append([x + i, y + j, z + k, w + l])
    return polygons

def binary_to_integer(binary_tuple):
    result = 0
    for i in range(len(binary_tuple)):
        result = result * 2 + binary_tuple[i]
    return result

import re

def remove_lowercase(string):
    return re.sub(r'[^a-z]', '', string)

def heap_queue_smallest(numbers, k):
    heap = []
    for num in numbers:
        heap.append((num, num))
    heap.sort()
    return [heap[0][1] for _ in range(k)]

def gcd(a, b):
    if a == 0:
        return b
    return gcd(b % a, a)

def concatenate_elements(elements):
    result = ""
    for element in elements:
        result += element
    return result

print(concatenate_elements(['hello','there','have','a','rocky','day']))

def num_comm_div(a, b):
    if a == 0 or b == 0:
        return 0
    else:
        return min(a, b) // max(a, b)

def add_consecutive_nums(nums):
    result = []
    for i in range(len(nums)):
        if i == 0:
            result.append(nums[i])
        else:
            if nums[i] == nums[i-1] + 1:
                result.append(nums[i])
            else:
                result.append(nums[i-1] + 1)
    return result

def sum_Of_Series(n):
    sum = 0
    for i in range(1, n+1):
        sum += i**3
    return sum

print(sum_Of_Series(5))

def re_order(arr):
    zeroes = 0
    for i in range(len(arr)):
        if arr[i] == 0:
            zeroes += 1
    for i in range(zeroes):
        arr.pop()
    for i in range(len(arr)):
        if arr[i] != 0:
            arr.append(arr[i])
    return arr

def permutation_coefficient(n, k):
    if k == 0:
        return 1
    elif k == 1:
        return n
    else:
        return n * permutation_coefficient(n - 1, k - 1)

def same_order(list1, list2):
    if len(list1) != len(list2):
        return False
    for i in range(len(list1)):
        if list1[i] != list2[i]:
            return False
    return True

def average_Odd(n):
    sum = 0
    for i in range(1, n+1, 2):
        sum += i
    return sum / 2

print(average_Odd(9))

def no_of_subsequences(arr, k):
    count = 0
    for i in range(len(arr)):
        for j in range(i+1, len(arr)+1):
            if arr[i] * arr[j] < k:
                count += 1
    return count
